mapper.update:
UPDATE member
SET member_delete_yn = 1
WHERE member_id = #{member_id};

mapper.select:
SELECT m.*,
       (
           SELECT COUNT(*)
           FROM follow f
           WHERE f.followed_member_id = m.member_id
       ) AS followerNum
FROM member m
WHERE m.member_id = #{member_id}
  AND m.member_delete_yn = 0;
